//! orbital-hvac — cabin thermal control for the station's habitat ring.
//!
//! The control chain is: [`OrbitalHvac`] runs a [`Pid`] loop whose output drives
//! a [`SolarShadeArray`], which talks to the shade motor bus via an `Actuator`.

pub mod actuator;
pub mod hvac;
pub mod pid;
pub mod shade;

pub use hvac::OrbitalHvac;
pub use pid::Pid;
pub use shade::SolarShadeArray;

base_files.src/pid.rs:
//! Minimal PID loop. Used by the orbital HVAC to hold cabin temperature by
//! trimming the solar shade. Gains are tuned for the ~90-minute orbital day.

pub struct Pid {
    kp: f64,
    ki: f64,
    kd: f64,
    integral: f64,
    last_error: f64,
}

impl Pid {
    pub fn new(kp: f64, ki: f64, kd: f64) -> Self {
        Self { kp, ki, kd, integral: 0.0, last_error: 0.0 }
    }

    /// Advance one control tick. `dt` is seconds since the last call.
    pub fn step(&mut self, setpoint: f64, measured: f64, dt: f64) -> f64 {
        let error = setpoint - measured;
        self.integral += error * dt;
        let derivative = (error - self.last_error) / dt;
        self.last_error = error;
        self.kp * error + self.ki * self.integral + self.kd * derivative
    }
}

base_files.src/actuator.rs:
//! Thin wrapper over the shade motor bus. The bus occasionally NAKs a write
//! during a comms blackout; callers are expected to retry.

pub struct Actuator {
    bank_id: u8,
}

#[derive(Debug)]
pub enum ActuatorError {
    Timeout,
    OutOfRange(f64),
}

impl Actuator {
    pub fn new(bank_id: u8) -> Self {
        Self { bank_id }
    }

    pub fn write(&self, opacity: f64) -> Result<(), ActuatorError> {
        // Real bus I/O elided for the sample repo.
        let _ = (self.bank_id, opacity);
        Ok(())
    }
}

base_files.src/shade.rs:
//! Drives the station's SolarShadeArray — the louvered shade that sets how much
//! sunlight reaches the radiators. Dimming to 0.0 is full shade, 1.0 is full sun.

use crate::actuator::{Actuator, ActuatorError};

/// One panel bank of the orbital shade. `opacity` is 0.0 (clear) .. 1.0 (opaque).
pub struct SolarShadeArray {
    actuator: Actuator,
    opacity: f64,
}

impl SolarShadeArray {
    pub fn new(actuator: Actuator) -> Self {
        Self { actuator, opacity: 0.0 }
    }

    /// Set shade opacity. Callers pass a PID output that can briefly exceed 1.0
    /// on a large setpoint step; today we forward it straight to the actuator.
    pub fn dim_to(&mut self, opacity: f64) -> Result<(), ActuatorError> {
        self.opacity = opacity;
        self.actuator.write(opacity)
    }

    pub fn opacity(&self) -> f64 {
        self.opacity
    }
}

