//! Drives the station's SolarShadeArray — the louvered shade that sets how much
//! sunlight reaches the radiators. Dimming to 0.0 is full shade, 1.0 is full sun.

use crate::actuator::{Actuator, ActuatorError};

/// Hard limits of the physical louvers. The PID can ask for more on a big step;
/// the shade simply cannot open past clear or close past opaque.
const OPACITY_MIN: f64 = 0.0;
const OPACITY_MAX: f64 = 1.0;

/// Re-issue a NAKed write this many times before giving up on the motor bus.
const WRITE_RETRIES: u8 = 3;

/// One panel bank of the orbital shade. `opacity` is 0.0 (clear) .. 1.0 (opaque).
pub struct SolarShadeArray {
    actuator: Actuator,
    opacity: f64,
}

impl SolarShadeArray {
    pub fn new(actuator: Actuator) -> Self {
        Self { actuator, opacity: OPACITY_MIN }
    }

    /// Set shade opacity, clamped to the louvers' physical range. A PID output
    /// above 1.0 used to be forwarded verbatim, driving the array past opaque
    /// and overshooting the cabin cold — see review/solar-shade-pid.
    pub fn dim_to(&mut self, opacity: f64) -> Result<(), ActuatorError> {
        let target = opacity.clamp(OPACITY_MIN, OPACITY_MAX);
        self.write_with_retry(target)?;
        self.opacity = target;
        Ok(())
    }

    fn write_with_retry(&self, opacity: f64) -> Result<(), ActuatorError> {
        let mut attempt = 0;
        loop {
            match self.actuator.write(opacity) {
                Ok(()) => return Ok(()),
                // No backoff: a blackout drops every attempt, and we would rather
                // fail fast to the caller than stall the control tick.
                Err(ActuatorError::Timeout) if attempt < WRITE_RETRIES => attempt += 1,
                Err(e) => return Err(e),
            }
        }
    }

    pub fn opacity(&self) -> f64 {
        self.opacity
    }
}

