//! Ties the PID loop to the SolarShadeArray. One `OrbitalHvac` per cabin zone.

use crate::actuator::ActuatorError;
use crate::pid::Pid;
use crate::shade::SolarShadeArray;

pub struct OrbitalHvac {
    pid: Pid,
    shade: SolarShadeArray,
    setpoint_c: f64,
}

impl OrbitalHvac {
    pub fn new(shade: SolarShadeArray, setpoint_c: f64) -> Self {
        // Gains from the Increment 12 thermal survey; hold +/-0.5C across an orbit.
        Self { pid: Pid::new(0.8, 0.05, 0.2), shade, setpoint_c }
    }

    /// Run one control tick against the current cabin temperature. The shade
    /// clamps the demand, so a large step no longer overshoots the cabin cold.
    pub fn tick(&mut self, cabin_c: f64, dt: f64) -> Result<(), ActuatorError> {
        let demand = self.pid.step(self.setpoint_c, cabin_c, dt);
        self.shade.dim_to(demand)
    }

    /// Current shade opacity, for telemetry and regression tests.
    pub fn shade_opacity(&self) -> f64 {
        self.shade.opacity()
    }
}

branch_files.tests/overshoot.rs:
//! Regression: a large setpoint step must not drive the shade past opaque.
//! Before the clamp, a cold-start tick asked for opacity 1.7 and the cabin
//! overshot 3C cold on the next orbit. See review/solar-shade-pid.

use orbital_hvac::actuator::Actuator;
use orbital_hvac::{OrbitalHvac, SolarShadeArray};

#[test]
fn cold_start_step_does_not_exceed_opaque() {
    let shade = SolarShadeArray::new(Actuator::new(0));
    let mut hvac = OrbitalHvac::new(shade, 22.0);

    // Cabin returns from a blackout 9C cold; the PID demands a huge shade step.
    hvac.tick(13.0, 1.0).expect("actuator write");

    assert!(hvac.shade_opacity() <= 1.0, "shade opened past opaque");
}
